def count_overlaps(A, B):
    count = 0
    for i in A:
        for j in B:
            if max(i[0], j[0]) <= min(i[1], j[1]):
                count += 1
    return count

def is_valid(intervals, K):
    unique_points = sorted(list(set([x for i, j in intervals for x in (i, j)])))
    for p in unique_points:
        count = 0
        for i, j in intervals:
            if i <= p <= j:
                count += 1
        if count > K:
            return False
    return True

